with open('/app/resources/treasury_bulletin_2014_06.json', 'r') as f:
    data = json.load(f)

# Look for any keys containing estimates
def find_keys(d, target=''):
    results = []
    if isinstance(d, dict):
        for k, v in d.items():
            if target.lower() in str(k).lower():
                results.append(k)
            results.extend(find_keys(v, target))
    elif isinstance(d, list):
        for item in d:
            results.extend(find_keys(item, target))
    return results

# Check for estimates
print("Looking for 'Est' or 'estimate' keys...")
